{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/pricing-card.json
    A plan as a card: name, tagline, price per month, the features, a call to action and an optional slot for more actions. Text comes in through `labels`; the plan is data.
    Props (p): plan, labels, current, emphasis, density, billing, footer (slot: plan). *}
{var $v_plan = ($p['plan'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_current = ($p['current'] ?? null)}
{var $v_emphasis = ($p['emphasis'] ?? 'auto')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_billing = ($p['billing'] ?? 'monthly')}
{var $v_stand = ui_and([ui_get($v_plan, ['highlighted']), ui_eq($v_emphasis, 'auto')])}
{var $v_yearlyOn = ui_and([ui_eq($v_billing, 'annual'), ui_gt(ui_get($v_plan, ['yearly']), 0)])}
{var $v_amount = (ui_t($v_yearlyOn) ? ui_get($v_plan, ['yearly']) : ui_get($v_plan, ['price']))}
{capture $c_16}
  {capture $c_5}
    {capture $c_2}
      {if ui_t($v_stand)}
        {capture $c_1}
          {=ui_text(ui_get($v_labels, ['popular']))}
        {/capture}
        {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'default', 'Size' => 'default'], 'children' => $c_1])|noescape}
      {/if}
    {/capture}
    {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'flex min-h-6 items-center', 'Attrs' => ui_attrs(['data-slot', 'badge-slot'])], 'children' => $c_2])|noescape}
    {capture $c_3}
      {=ui_text(ui_get($v_plan, ['name']))}
    {/capture}
    {=ui_include('ui/card/card-title.latte', ['p' => ['As' => ui_i(3)], 'children' => $c_3])|noescape}
    {capture $c_4}
      {=ui_text(ui_get($v_plan, ['tagline']))}
    {/capture}
    {=ui_include('ui/card/card-description.latte', ['p' => [], 'children' => $c_4])|noescape}
  {/capture}
  {=ui_include('ui/card/card-header.latte', ['p' => ['Class' => 'flex flex-col gap-2'], 'children' => $c_5])|noescape}
  {capture $c_13}
    {capture $c_8}
      {capture $c_6}
        {if ui_t(ui_eq($v_amount, 0))}
          {=ui_text(ui_get($v_labels, ['free']))}
        {else}
          {=ui_text(ui_money($v_amount, ui_get($v_plan, ['currency'])))}
        {/if}
      {/capture}
      {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(2), 'Size' => '4xl', 'Weight' => 'bold'], 'children' => $c_6])|noescape}
      {if ui_t(ui_gt($v_amount, 0))}
        {capture $c_7}
          {=ui_text((ui_t($v_yearlyOn) ? ui_get($v_labels, ['perYear']) : ui_get($v_labels, ['perMonth'])))}
        {/capture}
        {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_7])|noescape}
      {/if}
    {/capture}
    {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Align' => 'baseline'], 'children' => $c_8])|noescape}
    {capture $c_9}
      {=ui_text(ui_tpl(ui_get($v_labels, ['seats']), [ui_get($v_plan, ['seats'])]))}
    {/capture}
    {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'medium'], 'children' => $c_9])|noescape}
    {capture $c_10}
      {=ui_text(ui_tpl(ui_get($v_labels, ['storage']), [ui_get($v_plan, ['storage'])]))}
    {/capture}
    {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_10])|noescape}
    {capture $c_12}
      {foreach ui_l(ui_get($v_plan, ['features'])) as $v_feature}
        {capture $c_11}
          {=ui_text($v_feature)}
        {/capture}
        {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => 'flex gap-2'], 'children' => $c_11])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/list/list.latte', ['p' => ['Tag' => 'ul', 'Class' => 'flex flex-col gap-2 text-sm'], 'children' => $c_12])|noescape}
  {/capture}
  {=ui_include('ui/card/card-content.latte', ['p' => ['Class' => ui_s(ui_cnv(['flex flex-1 flex-col', (ui_t(ui_eq($v_density, 'compact')) ? 'gap-2' : 'gap-4')]))], 'children' => $c_13])|noescape}
  {capture $c_15}
    {capture $c_14}
      {=ui_text(ui_get($v_labels, ['cta']))}
    {/capture}
    {=ui_include('ui/button/button.latte', ['p' => ['Variant' => ui_s((ui_t($v_stand) ? 'default' : 'outline')), 'Size' => 'default', 'Attrs' => ui_attrs(['data-testid', 'plan-select'])], 'children' => $c_14])|noescape}
    {if (($p['footer'] ?? null) !== null)}
      {=ui_include($p['footer']['t'], array_merge($p['footer']['v'], ['a0' => $v_plan]))|noescape}
    {/if}
  {/capture}
  {=ui_include('ui/card/card-footer.latte', ['p' => ['Class' => 'flex flex-wrap items-center gap-2'], 'children' => $c_15])|noescape}
{/capture}
{=ui_include('ui/block/block.latte', ['p' => ['Tag' => 'article', 'Class' => ui_s(ui_cnv(['flex flex-col gap-8 bg-card p-6 text-card-foreground inset-ring inset-ring-border rounded', 'flex h-full flex-col'])), 'Attrs' => ui_attrs(['data-slot', 'card', 'data-highlighted', (ui_t($v_stand) ? 'true' : 'false'), 'data-current', (ui_t($v_current) ? 'true' : 'false')])], 'children' => $c_16])|noescape}
